package com.learnagent.digest;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.event.EventListener;import org.springframework.boot.context.event.ApplicationReadyEvent;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;@Component@ConditionalOnProperty(prefix="learnagent.daily-digest",name="enabled",havingValue="true",matchIfMissing=true)public class DailyDigestScheduler{private final DailyDigestService service;public DailyDigestScheduler(DailyDigestService service){this.service=service;}@Scheduled(cron="${learnagent.daily-digest.cron:0 0 8 * * *}",zone="${learnagent.time-zone:Asia/Shanghai}")public void scheduled(){service.generateToday();}@EventListener(ApplicationReadyEvent.class)public void catchUp(){try{service.generateToday();}catch(RuntimeException ignored){}}}
